components-block-alert--alert-closeable.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlAlert } from '@domg-wc/components/block';

registerWebComponents([VlAlert]);

// De sluitknop verwijdert vl-alert uit de DOM en pas daarna volgt vl-alert-closed. Luister daarom op het element
// zelf: een listener op een parent of op document krijgt het event niet.
document.querySelector('vl-alert[closable]').addEventListener('vl-alert-closed', () => {
    console.log('melding gesloten');
});

components-block-alert--alert-alert-dial.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlAlert } from '@domg-wc/components/block';

registerWebComponents([VlAlert, VlButtonComponent]);

// Bij alert-role="alertdialog" verplaatst de component de focus niet zelf: doe het zodra de melding verschijnt.
// vl-alert rendert asynchroon; wacht op updateComplete, anders bestaat de focusbare melding nog niet.
const alert = document.querySelector('vl-alert[alert-role="alertdialog"]');
await alert.updateComplete;
alert.focus(); // verplaatst de focus naar de melding zelf

